// Same actual publication owner, separate PG selected-target authority. No
// copied receipt, timestamp, serialized flag or serving/creator conversion.
struct PgPublicationVerifiedChange{m:PreparedPublication,raw:String,old:Option<String>,new:String,inspection:journal_fs::InstallInspection,paths:crate::storage::restoration::linux::engine_transfer::PgPublicationPaths}
pub(crate) struct PgPublicationRecoveryAck{selection:crate::storage::restoration::linux::engine_transfer::PgPublicationSelection,changes:Vec<PgPublicationVerifiedChange>}
pub(crate) async fn recover_pg_for_verification(selection:crate::storage::restoration::linux::engine_transfer::PgPublicationSelection,conn:&mut AnyConnection)->anyhow::Result<PgPublicationRecoveryAck>{
 use anyhow::ensure;
 selection.check_in(conn).await?;let stages=journal_fs::inventory(selection.path(),NS,!selection.expected().is_empty())?;ensure!(stages.iter().cloned().collect::<std::collections::BTreeSet<_>>()==selection.expected().keys().cloned().collect(),"Original publication stages/receipts differ");
 let mut changes=Vec::new();for(op,original)in selection.expected(){selection.check_in(conn).await?;let m=load(selection.path(),op).map_err(|e|anyhow::anyhow!("Original publication stage unavailable:{e:?}"))?;let row:(String,Option<String>)=sqlx::query_as("SELECT manifest_json,verified_at FROM publication_receipts WHERE op_id=$1").bind(op).fetch_one(&mut *conn).await?;ensure!(row.0==*original&&receipt(conn,op).await.map_err(|e|anyhow::anyhow!("Original receipt validation refused:{e:?}"))?.as_ref()==Some(&m),"Original publication identity/raw manifest differs");
  let inspection=journal_fs::inspect_install(selection.path(),NS,&(&m.file).into(),true)?;ensure!(inspection.installed_present,"Original publication install absent");let mut paths=inspection.paths.iter().map(|p|p.relative.clone()).collect::<std::collections::BTreeSet<_>>();paths.insert(format!("{NS}/{op}/manifest.json"));if inspection.proof.is_some(){paths.insert(format!("{NS}/{op}/install-proof.json"));}let held=selection.hold_paths(&paths.into_iter().collect::<Vec<_>>())?;
  journal_fs::verify_install(selection.path(),NS,&m.file)?;held.fence()?;selection.check_in(conn).await?;
  let verified=chrono::Utc::now().to_rfc3339();ensure!(sqlx::query("UPDATE publication_receipts SET verified_at=$1 WHERE op_id=$2 AND manifest_json=$3").bind(&verified).bind(op).bind(original).execute(&mut *conn).await?.rows_affected()==1,"Actual publication-owner verification update did not match original receipt");
  held.fence()?;let after:(String,Option<String>)=sqlx::query_as("SELECT manifest_json,verified_at FROM publication_receipts WHERE op_id=$1").bind(op).fetch_one(&mut *conn).await?;ensure!(after.0==row.0&&after.1.as_deref()==Some(verified.as_str())&&receipt(conn,op).await.map_err(|e|anyhow::anyhow!("Actual acknowledged receipt unavailable:{e:?}"))?.as_ref()==Some(&m),"Actual publication-owner acknowledgment differs");ensure!(journal_fs::inspect_install(selection.path(),NS,&(&m.file).into(),true)?==inspection,"Publication install changed across actual owner verification");selection.check_in(conn).await?;changes.push(PgPublicationVerifiedChange{m,raw:row.0,old:row.1,new:verified,inspection,paths:held});
 }
 let ack=PgPublicationRecoveryAck{selection,changes};ack.fence(conn).await?;Ok(ack)
}
impl PgPublicationRecoveryAck{
 pub(crate) fn changes(&self)->impl Iterator<Item=(&str,&str,Option<&str>,&str)>{self.changes.iter().map(|v|(v.m.op_id(),v.raw.as_str(),v.old.as_deref(),v.new.as_str()))}
 pub(crate) async fn fence(&self,conn:&mut AnyConnection)->anyhow::Result<()>{use anyhow::ensure;self.selection.check_in(conn).await?;for change in &self.changes{change.paths.fence()?;let actual:(String,Option<String>)=sqlx::query_as("SELECT manifest_json,verified_at FROM publication_receipts WHERE op_id=$1").bind(change.m.op_id()).fetch_one(&mut *conn).await?;ensure!(actual.0==change.raw&&actual.1.as_deref()==Some(change.new.as_str())&&receipt(conn,change.m.op_id()).await.map_err(|e|anyhow::anyhow!("Acknowledged publication receipt unavailable:{e:?}"))?.as_ref()==Some(&change.m),"Actual publication-owner raw receipt changed");journal_fs::verify_install(self.selection.path(),NS,&change.m.file)?;ensure!(journal_fs::inspect_install(self.selection.path(),NS,&(&change.m.file).into(),true)?==change.inspection,"Acknowledged publication native install changed");change.paths.fence()?;}self.selection.check_in(conn).await}
}
